static z_t4423_t z_io_stat(z_t81_t path) {
    z_t4423_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    struct stat sb;
    int rc = stat(path_cstr, &sb);
    int e = errno;
    free(path_cstr);
    if (rc != 0) {
        z_t3393_t* boxed = (z_t3393_t*)z_xmalloc(sizeof(z_t3393_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_T4423_TAG_0;
        result.data = boxed;
        return result;
    }
    z_t4415_t fs = {0};
    z_io_fill_filestat(&fs, &sb);
    z_t4415_t* boxed = (z_t4415_t*)z_xmalloc(sizeof(z_t4415_t));
    *boxed = fs;
    result.tag = Z_T4423_TAG_1;
    result.data = boxed;
    return result;
}


static z_t4137_t z_io_writeText(
    z_t81_t path, z_t81_t content
) {
    return z_io_write_common(path, content, O_WRONLY | O_CREAT | O_TRUNC);
}


